<template>
  <section><div class="actions" style="justify-content:space-between;align-items:center"><div><p class="muted">Konts</p><h1>Manas rezervācijas</h1></div><NuxtLink class="button" to="/booking">Jauna rezervācija</NuxtLink></div>
    <div v-if="error" class="error">{{error}}</div><div class="card table-wrap"><table class="table"><thead><tr><th>Datums</th><th>Laiks</th><th>Auto</th><th>Cena</th><th>Statuss</th><th></th></tr></thead><tbody><tr v-for="b in bookings" :key="b.id"><td>{{b.booking_date}}</td><td>{{String(b.booking_time).slice(0,5)}}</td><td>{{b.make}} {{b.model}}<br><small class="muted">{{b.registration_number}}</small></td><td>{{(b.price_cents/100).toFixed(2)}} €</td><td><span class="badge">{{labels[b.status]||b.status}}</span></td><td><button v-if="['pending','confirmed'].includes(b.status)" class="button secondary" @click="cancel(b.id)">Atcelt</button></td></tr><tr v-if="!bookings.length"><td colspan="6" class="muted">Rezervāciju vēl nav.</td></tr></tbody></table></div>
  </section>
</template>
<script setup lang="ts">const bookings=ref<any[]>([]);const error=ref('');const labels:any={pending:'Gaida',confirmed:'Apstiprināta',completed:'Pabeigta',cancelled_customer:'Atcelta',cancelled_admin:'Atcelta administrācijā',no_show:'Neieradās'};async function load(){try{bookings.value=(await $fetch<any>('/api/bookings')).bookings}catch(e:any){error.value='Lai skatītu rezervācijas, ielogojies.'}}async function cancel(id:string){if(!confirm('Atcelt rezervāciju?'))return;try{await $fetch(`/api/bookings/${id}`,{method:'DELETE'});await load()}catch(e:any){error.value=e?.data?.statusMessage||'Neizdevās atcelt rezervāciju.'}}await load()</script>
